#!/usr/bin/env python3
"""Emit the user's own turns from Claude Code transcripts as JSON lines.

Baseline and follow-up measurements only compare if both runs apply the same
filter, so the selection rules live here rather than in an ad-hoc command.
"""

import argparse
import datetime as dt
import json
import os
import sys

WRAPPERS = (
    "<command-name>",
    "<command-message>",
    "<local-command-stdout>",
    "<local-command-caveat>",
    "<system-reminder>",
    "Caveat: The messages below were generated by the user",
    "Base directory for this skill:",
    "[Request interrupted",
    "<task-notification>",
    "This session is being continued from a previous conversation",
    "Another Claude session sent a message",
    "<teammate-message",
)


def parse_day(value, end_of_day=False):
    day = dt.datetime.strptime(value, "%Y-%m-%d").replace(tzinfo=dt.timezone.utc)
    return day + dt.timedelta(days=1) if end_of_day else day


def block_text(content):
    """Join the text the user typed, dropping injected blocks block by block."""
    if isinstance(content, str):
        content = [{"type": "text", "text": content}]
    if not isinstance(content, list):
        return ""
    parts = [b.get("text", "") for b in content
             if isinstance(b, dict) and b.get("type") == "text"]
    kept = [p.strip() for p in parts if p.strip() and not p.strip().startswith(WRAPPERS)]
    return "\n".join(kept)


def is_authored(record, text):
    return bool(text.strip()) and not (record.get("isMeta") or record.get("isSidechain"))


def turns(path, since, until, context):
    project = os.path.basename(os.path.dirname(path))
    previous_assistant = ""
    with open(path, errors="replace") as handle:
        for line in handle:
            try:
                record = json.loads(line)
            except ValueError:
                continue
            message = record.get("message")
            # A message typed while the agent works is delivered into the running turn and is
            # recorded only as a queue operation, never as a user message.
            mid_turn = (record.get("type") == "queue-operation"
                        and record.get("reason") == "absorbed_mid_turn")
            if mid_turn:
                text = block_text(record.get("content"))
            elif isinstance(message, dict):
                text = block_text(message.get("content"))
                if message.get("role") == "assistant":
                    if text.strip():
                        previous_assistant = text.strip()
                    continue
                if message.get("role") != "user":
                    continue
            else:
                continue
            if not is_authored(record, text):
                continue
            stamp = record.get("timestamp")
            if not stamp:
                continue
            when = dt.datetime.fromisoformat(stamp.replace("Z", "+00:00"))
            if when < since or when >= until:
                continue
            yield {
                "timestamp": stamp,
                "project": project,
                "session": record.get("sessionId"),
                "cwd": record.get("cwd"),
                "preceding_assistant": previous_assistant[:context],
                "text": text.strip(),
                "mid_turn": mid_turn,
            }


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--since", required=True, help="inclusive UTC day, YYYY-MM-DD")
    parser.add_argument("--until", help="inclusive UTC day, YYYY-MM-DD (default: today)")
    parser.add_argument("--root", default=os.path.expanduser("~/.claude/projects"))
    parser.add_argument("--project", action="append", default=[],
                        help="restrict to project directory names containing this string")
    parser.add_argument("--context", type=int, default=600,
                        help="characters of the preceding assistant turn to include")
    args = parser.parse_args()

    since = parse_day(args.since)
    until = parse_day(args.until, end_of_day=True) if args.until else \
        dt.datetime.now(dt.timezone.utc)

    found = files = 0
    sessions = set()
    for project in sorted(os.listdir(args.root)):
        if args.project and not any(f in project for f in args.project):
            continue
        directory = os.path.join(args.root, project)
        if not os.path.isdir(directory):
            continue
        for name in sorted(os.listdir(directory)):
            if not name.endswith(".jsonl"):
                continue
            path = os.path.join(directory, name)
            # A session's last write bounds its records, so older files hold nothing in range.
            if dt.datetime.fromtimestamp(os.path.getmtime(path), dt.timezone.utc) < since:
                continue
            files += 1
            for turn in turns(path, since, until, args.context):
                found += 1
                sessions.add(turn["session"])
                print(json.dumps(turn, ensure_ascii=False))
    # Sessions that contributed turns, not files scanned: the scanned count includes transcripts
    # touched in the window that contain no authored turn, and it drifts while sessions are live.
    print("%d turns from %d sessions (%d transcripts scanned) (%s..%s)"
          % (found, len(sessions), files, since.date(), until.date()), file=sys.stderr)


if __name__ == "__main__":
    main()
